export const docxTemplateCatalog = rawDocxTemplateCatalog.map(template => {
  if (template.code === "E1") return {
    ...template,
    bodyHtml: template.bodyHtml
      .replace("{{date_1}}: {{times}}", "{{date_1}}: {{times_1}}")
      .replace("{{date_2}}: {{times}}", "{{date_2}}: {{times_2}}")
      .replace("{{date_3}}: {{times}}", "{{date_3}}: {{times_3}}"),
    variables: template.variables.flatMap(variable => variable.key === "times"
      ? [{ key: "times_1", label: "Times 1" }, { key: "times_2", label: "Times 2" }, { key: "times_3", label: "Times 3" }]
      : [variable]),
  };
  if (template.code === "M1" && !template.bodyHtml.includes("{{booking_link}}")) return {
    ...template,
    bodyHtml: `${template.bodyHtml}<p><a href="{{booking_link}}">Book your MIAM appointment</a></p>`,
  };
  return template;
});
